    "solution.py": "def file_suffix(name):
    """
    파일 이름에서 확장자를 추출하는 함수입니다.

    입력: 경로 구분자 없이 영문 대소문자, 숫자, 점, 하이픈으로만 된 파일 이름
    반환: 점 다음 부분을 반환합니다.

    주의: 이 구현은 '이름 안에 점이 정확히 하나 있고 맨 앞이나 맨 끝에 있지 않은 보통 파일'에 대한 요구사항을 충족합니다.
    다른 경우 (점 여러 개, 점으로 시작, 확장자 없음 등) 는 담당자 확인이 필요하므로 현재는 예외를 발생시킵니다.
    """
    # 점이 정확히 하나여야 함
    if name.count('.') != 1:
        raise ValueError("파일 이름에 점이 정확히 하나여야 합니다.")

    # 점이 맨 앞이나 맨 끝에 있지 않아야 함
    if name.startswith('.') or name.endswith('.'):
        raise ValueError("파일 이름의 점은 맨 앞이나 맨 끝에 있을 수 없습니다.")

    # 점을 분리하여 확장자 부분 반환
    return name.split('.')[-1]
  }"
